# FILE 3: .claude/skills/rls-migration-guard/scripts/check_rls.mjs (DevOps)
========================================================================
import fs from 'node:fs';
import path from 'node:path';

const sqlFile = process.argv[2];
if (!sqlFile || !fs.existsSync(sqlFile)) {
  console.error('Thieu duong dan file SQL migration.');
  process.exit(2);
}
const sql = fs.readFileSync(sqlFile, 'utf8');
const tables = [...sql.matchAll(/CREATE TABLE\s+(?:IF NOT EXISTS\s+)?([\w."]+)/gi)].map((m) => m[1]);

const violations = [];
for (const tbl of tables) {
  const hasEnable = new RegExp(`ALTER TABLE\\s+${tbl}\\s+ENABLE ROW LEVEL SECURITY`, 'i').test(sql);
  const hasForce = new RegExp(`ALTER TABLE\\s+${tbl}\\s+FORCE ROW LEVEL SECURITY`, 'i').test(sql);
  if (!hasEnable || !hasForce) {
    violations.push(`${tbl}: thieu ENABLE/FORCE ROW LEVEL SECURITY`);
  }
}
if (violations.length > 0) {
  console.error('[RLS_GUARD_BLOCK]\n' + violations.join('\n'));
  process.exit(2);
}
console.log(`PASS: ${tables.length} bang da bat du FORCE RLS.`);
